package com.example.statusdrafter.service; import com.example.statusdrafter.entity.*; import com.example.statusdrafter.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class StatusUpdateService {private final StatusUpdateRepository repo; public StatusUpdateService(StatusUpdateRepository r){repo=r;} public List<StatusUpdate> mine(User u){return repo.findByEmployeeOrderByUpdateDateDesc(u);} public List<StatusUpdate> recent(User u){return repo.findTop5ByEmployeeOrderByUpdateDateDesc(u);} public StatusUpdate get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Status update not found"));} public StatusUpdate save(StatusUpdate s,User u){s.setEmployee(u); if(s.getId()==null){var existing=repo.findByEmployeeAndUpdateDate(u,s.getUpdateDate()); if(existing.isPresent()){s.setId(existing.get().getId());}} return repo.save(s);} public void delete(Long id,User u){StatusUpdate s=get(id);if(!s.getEmployee().getId().equals(u.getId())&&u.getRole()!=User.Role.ADMIN)throw new SecurityException("Unauthorized");repo.delete(s);} public long countToday(User u){return repo.countByEmployeeAndUpdateDate(u,LocalDate.now());} }
